      entryPoint,
      projectType: "Flow",
      apiConfig,
      organizationName: config.organizationName,
      callbacks,
      pollInterval,
      maxPolls: options?.maxPolls ?? 300,
      beginSessionPayload: inputs ? JSON.stringify(inputs) : undefined
